import React from 'react';

import { MeterBarSegment } from '../../shared/components/meter-bar-segment/MeterBarSegment.js';
import { useMultiMeterBarHighlightedSegments } from '../hooks/store/selectors.js';
import { useSegmentHandlers } from '../hooks/useSegmentHandlers.js';

interface MultiMeterBarSegmentProps {
  segmentId: string;
  segmentColor: string;
  segmentWidth: number;
  previousSegmentsWidth: number;
}

export const MultiMeterBarSegment = (props: MultiMeterBarSegmentProps) => {
  const { previousSegmentsWidth, segmentColor, segmentWidth, segmentId } =
    props;
  const highlightedSegments = useMultiMeterBarHighlightedSegments();
  const higlightedSegmentIds = highlightedSegments?.map((s) => s.id);
  const isHighlighted =
    !highlightedSegments || higlightedSegmentIds?.includes(segmentId);

  const {
    handleSegmentMouseClick,
    handleSegmentMouseEnter,
    handleSegmentMouseLeave,
    handleSegmentMouseMove,
  } = useSegmentHandlers();

  return (
    <MeterBarSegment
      color={segmentColor}
      width={segmentWidth}
      highlighted={isHighlighted}
      start={previousSegmentsWidth}
      onClickAction={(e) => handleSegmentMouseClick(e, segmentId)}
      onMouseEnterAction={() => handleSegmentMouseEnter(segmentId)}
      onMouseLeaveAction={handleSegmentMouseLeave}
      onMouseMoveAction={handleSegmentMouseMove}
    />
  );
};

MultiMeterBarSegment['displayName'] = 'MultiMeterBarSegment';
